INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A clavícula é o primeiro osso a ossificar e o único osso longo que se ossifica em membrana. Em caso de fratura, a maioria ocorre no terço médio, devido à sua curvatura. Qual músculo, ao tracionar o fragmento medial superiormente após uma fratura, é responsável pelo desvio característico visível no exame físico?","options":{"a":"Deltoide.","b":"Peitoral maior.","c":"Esternocleidomastoideo.","d":"Trapézio.","e":"Subclávio."},"answer":"c","rationale":"Na fratura de clavícula, o músculo esternocleidomastoideo traciona o fragmento medial para cima, enquanto o peso do braço e a ação do peitoral maior puxam o fragmento lateral para baixo e medialmente. O subclávio, por sua vez, pode proteger os vasos subclávios subjacentes em caso de fraturas não cominutivas.","option_rationales":{"a":"Errada. O deltoide traciona o fragmento lateral.","b":"Errada. O peitoral maior traciona o fragmento lateral medialmente.","c":"Correta. Tração superior do fragmento medial.","d":"Errada. O trapézio atua na estabilização posterior da escápula.","e":"Errada. O subclávio atua puxando a clavícula inferiormente, não o fragmento medial superiormente."},"difficulty":"Fácil","tags":["Anatomia","Osteologia","Membro Superior"]}', 'e612e116c663c142be479e6b8ea8c216', 20, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo iliopsoas é o principal flexor do quadril. Ele é formado pela união dos músculos psoas maior e ilíaco. O psoas menor, quando presente, situa-se anteriormente ao psoas maior. Qual é o local de inserção distal comum do tendão do músculo iliopsoas no fêmur?","options":{"a":"Trocânter maior.","b":"Trocânter menor.","c":"Linha pectínea.","d":"Crista intertrocantérica.","e":"Fossa trocantérica."},"answer":"b","rationale":"O tendão do iliopsoas insere-se no trocânter menor do fêmur. É o mais potente flexor da articulação do quadril, essencial para a marcha e para levantar-se da posição sentada.","option_rationales":{"a":"Errada. Inserção de glúteos e piriforme.","b":"Correta. Localização clássica de inserção do iliopsoas.","c":"Errada. Local de inserção do músculo pectíneo.","d":"Errada. Marco ósseo posterior do fêmur.","e":"Errada. Local de inserção do músculo obturador externo."},"difficulty":"Fácil","tags":["Anatomia","Miologia","Membro Inferior"]}', '5214cd8573e610beaa9530f83407ba8f', 21, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A anatomia do pescoço é organizada em triângulos delimitados por músculos proeminentes. O triângulo carótico, local de palpação do pulso carotídeo, é delimitado por quais músculos?","options":{"a":"Esternocleidomastoideo, ventre superior do omo-hioideo e ventre posterior do digástrico.","b":"Trapézio, clavícula e esternocleidomastoideo.","c":"Mandíbula, ventre anterior e posterior do digástrico.","d":"Esternocleidomastoideo, esterno-hioideo e mandíbula.","e":"Escaleno anterior, escaleno médio e 1ª costela."},"answer":"a","rationale":"O triângulo carótico é delimitado pelo bordo anterior do músculo esternocleidomastoideo, pelo ventre posterior do músculo digástrico e pelo ventre superior do músculo omo-hioideo. Contém a artéria carótida comum e sua bifurcação.","option_rationales":{"a":"Correta. Limites clássicos do triângulo carótico.","b":"Errada. Limites do triângulo cervical posterior.","c":"Errada. Limites do triângulo submandibular.","d":"Errada. Descrição incorreta de triângulos cervicais.","e":"Errada. Limites do espaço interescalênico."},"difficulty":"Média","tags":["Anatomia","Miologia","Pescoço"]}', 'a7b48fc64e4949f3c931cb9f4c3ef606', 22, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Dentre os ossos do tarso, qual é o único que não possui inserções musculares ou tendinosas diretas, transmitindo todo o peso do corpo da tíbia para o calcâneo e o restante do pé?","options":{"a":"Calcâneo.","b":"Talus (astrágalo).","c":"Navicular.","d":"Cuboide.","e":"Cuneiforme medial."},"answer":"b","rationale":"O talus é o osso do tarso que se articula com a tíbia e a fíbula na articulação do tornozelo. Ele é recoberto por cartilagem articular em grande parte de sua superfície e é único por não possuir nenhuma inserção muscular ou tendinosa em suas faces.","option_rationales":{"a":"Errada. O calcâneo recebe a inserção do tendão calcâneo (Aquiles).","b":"Correta. O talus não possui inserções musculares diretas.","c":"Errada. O tibial posterior insere-se no navicular.","d":"Errada. O tibial posterior também tem expansões para o cuboide.","e":"Errada. O tibial anterior e o tibial posterior inserem-se nos cuneiformes."},"difficulty":"Média","tags":["Anatomia","Osteologia","Membro Inferior"]}', '2e9ced17390ba2d2c558862306908dce', 23, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo diafragma possui três grandes aberturas (hiatos) que permitem a passagem de estruturas fundamentais entre essas cavidades. O forame da veia cava localiza-se em qual porção do diafragma e em qual nível vertebral?","options":{"a":"Centro tendíneo Nível T8.","b":"Parte muscular vertebral; Nível T10.","c":"Pilar direito; Nível T12.","d":"Ligamento arqueado mediano; Nível L1.","e":"Trígono lombo-costal; Nível T12."},"answer":"a","rationale":"O forame da veia cava situa-se no centro tendíneo do diafragma, geralmente no nível da 8ª vértebra torácica (T8). Além da veia cava inferior, ramos do nervo frênico direito também atravessam essa abertura.","option_rationales":{"a":"Correta. Localização e nível vertebral do forame da veia cava.","b":"Errada. Nível T10 corresponde ao hiato esofágico.","c":"Errada. Nível T12 corresponde ao hiato aórtico.","d":"Errada. O ligamento arqueado mediano forma o hiato aórtico.","e":"Errada. O trígono lombo-costal é uma zona de fraqueza, não um hiato anatômico para grandes vasos."},"difficulty":"Fácil","tags":["Anatomia","Miologia","Diafragma"]}', '74282a3929e5b22c02cfcc5f777116e3', 24, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A parede abdominal anterior é formada por vários músculos e suas aponeuroses. Abaixo da linha arqueada (de Douglas), a bainha do músculo reto abdominal apresenta qual configuração anatômica em relação às lâminas aponeuróticas?","options":{"a":"Todas as aponeuroses passam posteriormente ao músculo reto.","b":"A aponeurose do oblíquo interno se divide, uma parte passando anterior e outra posterior ao reto.","c":"Todas as aponeuroses passam anteriormente ao músculo reto, deixando-o em contato direto com a fáscia transversalis posteriormente.","d":"A bainha é ausente abaixo da linha arqueada, sendo o músculo coberto apenas por pele.","e":"A aponeurose do transverso do abdome permanece posterior ao músculo reto."},"answer":"c","rationale":"Acima da linha arqueada, as aponeuroses se distribuem anterior e posteriormente ao reto. Porém, abaixo da linha arqueada (cerca de 5 cm abaixo da cicatriz umbilical), as aponeuroses do oblíquo externo, oblíquo interno e transverso do abdome passam todas ANTERIORMENTE ao músculo reto, formando a lâmina anterior da bainha. Posteriormente, o músculo reto fica em contato apenas com a fáscia transversalis e o peritônio.","option_rationales":{"a":"Errada. Isso não ocorre em nenhum nível.","b":"Errada. Isso ocorre APENAS acima da linha arqueada.","c":"Correta. Descrição clássica da transição na linha arqueada.","d":"Errada. O músculo sempre é protegido internamente por fáscia e peritônio.","e":"Errada. Abaixo da linha arqueada, ela passa para a frente."},"difficulty":"Difícil","tags":["Anatomia","Parede Abdominal","Miologia"]}', 'a6270b88c780a159f36c4182fe9f9a40', 25, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A fáscia toracolombar é uma estrutura aponeurótica complexa no dorso. Ela é composta por várias camadas. Qual desses músculos tem sua origem diretamente relacionada à camada posterior da fáscia toracolombar?","options":{"a":"Latíssimo do dorso (grande dorsal).","b":"Trapézio.","c":"Eretor da espinha.","d":"Multífido.","e":"Quadrado lombar."},"answer":"a","rationale":"O músculo latíssimo do dorso tem uma origem aponeurótica extensa na fáscia toracolombar (camada posterior), além dos processos espinhosos de T7-L5 e crista ilíaca.","option_rationales":{"a":"Correta. Origem principal do grande dorsal no dorso inferior.","b":"Errada. O trapézio origina-se na linha nucal e processos espinhosos cervicais/torácicos superiores.","c":"Errada. O eretor da espinha situa-se ENTRE as camadas da fáscia, mas não origina a camada posterior.","d":"Errada. O multífido é profundo e situa-se medialmente ao eretor.","e":"Errada. O quadrado lombar situa-se entre as camadas média e anterior da fáscia toracolombar."},"difficulty":"Média","tags":["Anatomia","Miologia","Dorso"]}', '0eb5b56371ee66de5431e608408621ab', 26, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O plexo coccígeo é formado por pequenos ramos nervosos. No entanto, o nervo frênico, essencial para a respiração, tem sua origem principal em qual plexo e quais raízes?","options":{"a":"Plexo braquial; C5-C7.","b":"Plexo cervical; C3-C5.","c":"Plexo lombar; L1-L3.","d":"Plexo sacral; S2-S4.","e":"Plexo celíaco; Nervos esplâncnicos."},"answer":"b","rationale":"O nervo frênico origina-se primordialmente do 4º nervo cervical (C4), com contribuições de C3 e C5 (mnemônico: \"C3, 4, 5 keep the diaphragm alive\"). Ele atravessa o pescoço e o tórax para inervar o diafragma.","option_rationales":{"a":"Errada. C5 pode contribuir, mas a origem é cervical superior.","b":"Correta. Origem clássica do nervo frênico.","c":"Errada. O plexo lombar supre membros inferiores e parede abdominal.","d":"Errada. O plexo sacral supre períneo e membros inferiores.","e":"Errada. O plexo celíaco é autonômico (simpático/parassimpático)."},"difficulty":"Fácil","tags":["Anatomia","Neuroanatomia","Sistema Respiratório"]}', 'c3007916cfa7506aec07d3f3de0bb56d', 27, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O canal do carpo é uma passagem estreita no punho por onde transitam tendões e o nervo mediano. Qual estrutura anatômica forma o teto (limite superficial) desse canal e cuja secção cirúrgica é o tratamento definitivo para a síndrome do túnel do carpo?","options":{"a":"Retináculo dos flexores (ligamento carpal transverso).","b":"Aponeurose palmar.","c":"Retináculo dos extensores.","d":"Ligamento colateral ulnar.","e":"Tendão do palmar longo."},"answer":"a","rationale":"O retináculo dos flexores é uma banda fibrosa resistente que se estende entre o escafoide/trapézio e o pisiforme/hamato. Ele forma o teto do túnel do carpo, mantendo os tendões flexores em posição. Seu espessamento pode comprimir o nervo mediano.","option_rationales":{"a":"Correta. Estrutura alvo na síndrome do túnel do carpo.","b":"Errada. A aponeurose palmar é superficial ao retináculo na palma da mão.","c":"Errada. O retináculo dos extensores localiza-se na face dorsal do punho.","d":"Errada. Estabiliza o lado medial da articulação do punho.","e":"Errada. O tendão do palmar longo passa SUPERFICIALMENTE ao retináculo e não compõe o teto do canal."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Aplicação Clínica"]}', '3cec99ac228f6204cb177e9f02000923', 28, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os músculos intercostais são fundamentais para a mecânica respiratória. Sobre a disposição de suas fibras, assinale a alternativa que descreve corretamente a orientação das fibras do músculo intercostal externo.","options":{"a":"De cima para baixo e de trás para frente (sentido das mãos no bolso).","b":"De cima para baixo e de frente para trás.","c":"Horizontalmente entre as costelas.","d":"Verticalmente unindo as bordas das costelas.","e":"Em sentido perpendicular às fibras do intercostal íntimo."},"answer":"a","rationale":"Os músculos intercostais externos têm suas fibras orientadas obliquamente, de cima para baixo e de trás para frente (anteroinferiormente). Essa orientação é análoga à dos músculos oblíquos externos do abdome e auxilia na elevação das costelas durante a inspiração.","option_rationales":{"a":"Correta. Orientação clássica \"mãos no bolso\".","b":"Errada. Esta seria a orientação inversa (intercostais internos).","c":"Errada. Nenhuma camada intercostal é puramente horizontal.","d":"Errada. Disposição incorreta.","e":"Errada. As fibras do intercostal íntimo têm a mesma direção que as do interno, sendo perpendiculares às do externo."},"difficulty":"Média","tags":["Anatomia","Miologia","Tórax"]}', 'd00ba6d070122cc6e6c918bfd75d2eeb', 29, 'draft');;);